# Anticipate: "Look at the top three cards of your library. / Put one of them into your hand and the
# rest on the bottom of your library in any order."  Sentence 2: See the Truth's B5b-one-of-rest-bottom tree.
look = A(Verb.LOOK_AT, {'controller': ControllerRef.YOU, 'count': QConst(value=3)})
top = (Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU, position=ZonePosition.TOP),)
one_and_rest = Seq(steps=(
    A(Verb.MOVE_ZONE, {
        'cards': Selector(count=QConst(value=1), mode=SelectorMode.ONE_OF, filter=FAnd(children=()), zones=top),
        'destination': Zone(kind=ZoneKind.HAND, controller=ControllerRef.YOU),
    }),
    A(Verb.MOVE_ZONE, {
        'cards': Selector(count=QConst(value=1), mode=SelectorMode.REST, filter=FAnd(children=()), zones=top),
        'destination': Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU, position=ZonePosition.BOTTOM),
    }),
))
abilities = [SpellAbility(kind=SpellKind.INSTANT, effect=Seq(steps=(look, one_and_rest)))]
